Translate("deDE", "azeroth", {
	title = "Azeroth",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Azeroth ist die Welt. Ihre Meere umschließen die Kontinente der {link:eastern-kingdoms}Östlichen Königreiche{/link}, {link:kalimdor}Kalimdor{/link} und das gefrorene Nordend, dazu unzählige Inseln. Dschungel, Wüsten, Wälder und Eisfelder liegen auf ihr Seite an Seite, und in jedem Land ruhen die Ruinen älterer Zeitalter unter den Städten der neuen. Es ist eine Welt vieler Völker und sehr langer Erinnerung. Wieder und wieder wurde sie von Mächten, die nach ihr gieren, zum Bluten gebracht, und wieder und wieder hat sie überdauert.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die ältesten Geschichten berichten, dass Azeroth von den Titanen geformt wurde, gottgleichen Wesen, die zwischen den Sternen reisten, um den Welten, die sie fanden, Ordnung zu bringen. Als sie nach Azeroth kamen, wurde es von tobenden Elementaren beherrscht und von uralten Übeln, die sich an der Welt festgesetzt hatten. Die Chroniken nennen diese Übel die Alten Götter. Die Titanen brachen die Macht beider. Sie banden die Elementarfürsten in einem Reich, das von der Welt getrennt ist, und sie kerkerten die Alten Götter tief unter der Erde ein, denn diese ließen sich nicht erschlagen, ohne die Welt selbst zu verwunden. Dann formten die Titanen das Land. Ihre Diener türmten die Berge auf, gruben die Täler und füllten die Meere. Die Irdenen, Wesen aus lebendem Stein, wurden eingesetzt, um die tiefen Orte der Welt zu hüten. Unter den Drachen erwählten die Titanen fünf und gaben jedem einen Teil ihrer Macht. Diese wurden die Aspekte, beauftragt, Azeroth zu schützen, wenn seine Schöpfer fort wären. Dann zogen die Titanen fort, und die Welt wurde ihren eigenen Völkern überlassen.]=],
		},
		{
			title = "Die Zeitalter der Welt",
			text = [=[• {b}Das Reich der Kaldorei.{/b} Im Herzen eines einzigen großen Kontinents lag der {link:well-of-eternity}Brunnen der Ewigkeit{/link}. An seinen Ufern errichteten die {link:night-elves}Nachtelfen{/link} unter {link:queen-azshara}Königin Azshara{/link} ein Reich der Wunder.
• {b}Der Krieg der Ahnen.{/b} Die rücksichtslose Magie der Hochgeborenen zog den Blick der {link:burning-legion}Brennenden Legion{/link} auf sich. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} kämpften die Nachtelfen um das Überleben der Welt, und die Zerstörung des Brunnens führte zur {link:great-sundering}Großen Zerschlagung{/link}. Der eine Kontinent zerbrach in viele.
• {b}Die jüngeren Völker.{/b} In den folgenden Zeitaltern schwanden die Reiche der {link:trolls}Trolle{/link}, und die {link:dwarves}Zwerge{/link} erwachten unter den Bergen. Die {link:high-elves}Hochelfen{/link} gründeten {link:quel-thalas}Quel'Thalas{/link}, und die Stämme der {link:humans}Menschen{/link} vereinten sich als {link:arathor}Arathor{/link}, um die {link:troll-wars}Trollkriege{/link} zu führen.
• {b}Das Zeitalter der {link:horde}Horde{/link}.{/b} Als sich das {link:dark-portal}Dunkle Portal{/link} öffnete, strömten die {link:orcs}Orcs{/link} einer anderen Welt nach Azeroth. Der {link:first-war}Erste Krieg{/link}, der {link:second-war}Zweite Krieg{/link} und der {link:third-war}Dritte Krieg{/link} folgten, jeder schrecklicher als der vorige.]=],
		},
		{
			title = "Ein geteilter Name",
			text = [=[Der Name Azeroth gehörte einst auch einem Königreich der {link:humans}Menschen{/link}. Die Verbannten der {link:arathi-highlands}Arathi{/link}, die sich in den südlichen Wäldern niederließen, nannten ihr neues Reich Azeroth, und seine {link:capital-city}Hauptstadt{/link} war {link:stormwind-city}Stormwind{/link}. Mit der Zeit wurde das Reich nach seiner Stadt benannt, und heute ist es das {link:kingdom-of-stormwind}Königreich Stormwind{/link}. Alte Soldaten des {link:first-war}Ersten Krieges{/link} sprechen noch manchmal von „Azeroth“ und meinen damit nur das Königreich, das sie verloren.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Der Dritte Krieg endete mit dem Fall von {link:archimonde}Archimonde{/link} am Fuß von {link:nordrassil}Nordrassil{/link}, doch Frieden brachte er nicht. Die {link:scourge}Geißel{/link} hält den Norden von {link:lordaeron}Lordaeron{/link}. Diener der Brennenden Legion suchen noch immer die Wälder Kalimdors heim. Die {link:alliance}Allianz{/link} und die {link:horde}Horde{/link}, die am {link:mount-hyjal}Berg Hyjal{/link} Seite an Seite standen, beobachten einander nun voller Argwohn über das {link:the-barrens}Brachland{/link} und die Wälder des Eschentals hinweg. Unter dem {link:blackrock-mountain}Blackrock{/link} dienen die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} einem Herrn aus lebendem Feuer. Azeroth hat jeden Krieg überlebt, der bisher auf ihm geführt wurde. Kein Chronist würde zu sagen wagen, dass es nicht fallen kann.]=],
		},
	},
})

Translate("deDE", "eastern-kingdoms", {
	title = "Östliche Königreiche",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Östlichen Königreiche erstrecken sich von den gefrorenen Gipfeln des {link:alterac-mountains}Alteracgebirges{/link} bis zu den Dschungeln des {link:stranglethorn-vale}Schlingendorntals{/link}. Sie sind die Heimat der {link:humans}Menschheit{/link}, der {link:dwarves}Zwerge{/link} und {link:gnomes}Gnome{/link} und der {link:high-elves}Hochelfen{/link} von {link:quel-thalas}Quel'Thalas{/link}. Hier standen die großen Königreiche der Menschen aus alter Zeit, und hier führte die {link:horde}Horde{/link} ihren ersten Krieg gegen {link:azeroth}Azeroth{/link}. Die Lande tragen die Narben jedes Krieges seither. Einst stolze Reiche liegen in Trümmern, und der Norden ist zu einem Land der Toten geworden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Vor der {link:great-sundering}Großen Zerschlagung{/link} waren diese Lande die östlichen Ausläufer eines einzigen Kontinents. Als der {link:well-of-eternity}Brunnen der Ewigkeit{/link} zerstört wurde, drangen die Meere herein und rissen sie fort. Was blieb, war ein Land, das bereits alt war. Die Titanen hatten hier ihre Werke hinterlassen, unter ihnen {link:uldaman}das Gewölbe von Uldaman{/link} im steinigen {link:badlands}Ödland{/link}. Ihre irdenen Diener schliefen in seinen Hallen. Über lange Zeitalter veränderten sich die Irdenen. Ihr Fleisch wurde weich und ihr Leben kurz, und aus ihnen gingen die {link:dwarves}Zwerge{/link} von Khaz Modan hervor. Ein anderes von den Titanen geschmiedetes Volk, so steht es geschrieben, brachte die {link:gnomes}Gnome{/link} hervor. Die {link:trolls}Trolle{/link} waren in diesen Landen noch älter. Die Amani beherrschten die nördlichen Wälder, und die Gurubashi hielten die südlichen Dschungel.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Ankunft der Elfen.{/b} Aus {link:kalimdor}Kalimdor{/link} verbannt, überquerten die Hochgeborenen das Meer und gründeten {link:quel-thalas}Quel'Thalas{/link} in den nördlichen Wäldern, auf Land, das die Amani als ihr eigenes beanspruchten.
• {b}Arathor.{/b} Die Menschenstämme des Nordens wurden von {link:thoradin}Thoradin{/link} geeint, der die Stadt {link:stromgarde-keep}Strom{/link} errichtete. Gemeinsam mit den Elfen zerschlugen seine Heere die Amani in den {link:troll-wars}Trollkriegen{/link}. Im Gegenzug lehrten die Elfen die {link:humans}Menschen{/link} die Wege der Magie von {link:arathor}Arathi{/link}, und Dalaran wurde später von den Magiern dieser Linie gegründet.
• {b}Die sieben Königreiche.{/b} Mit der Zeit zerfiel Arathor. Im Norden erhoben sich die Königreiche {link:lordaeron}Lordaeron{/link}, {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:alterac-mountains}Alterac{/link}, {link:dalaran}Dalaran{/link} und Stromgarde. Im Süden gründeten Verbannte der {link:arathi-highlands}Arathi{/link} das Reich, das zum {link:kingdom-of-stormwind}Königreich Stormwind{/link} wurde.
• {b}Die drei Hämmer.{/b} Unter den Bergen spalteten sich die {link:dwarves}Zwerge{/link} von {link:kingdom-of-ironforge}Ironforge{/link} in die Klans der Bronzebeard, der Wildhammer und der {link:dark-iron-dwarves}Dunkeleisen{/link}. Ihr Krieg endete im Feuer. Der Zauberer-Than der Dunkeleisen, {link:ruins-of-thaurissan}Thaurissan{/link}, rief Ragnaros, den Herrn des Feuers, herbei, und die Beschwörung türmte den {link:blackrock-mountain}Blackrock{/link} auf und versengte die Lande ringsum.
• {b}Die Kriege der {link:horde}Horde{/link}.{/b} Im Süden öffnete sich das {link:dark-portal}Dunkle Portal{/link}. {link:stormwind-city}Stormwind{/link} fiel im {link:first-war}Ersten Krieg{/link}. Die {link:alliance}Allianz{/link} von Lordaeron warf die Horde im {link:second-war}Zweiten Krieg{/link} zurück. Dann kamen die Seuche des Untodes, das {link:culling-of-stratholme}Ausmerzen von Stratholme{/link} und der {link:fall-of-lordaeron}Fall von Lordaeron{/link}.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[{link:stormwind-city}Stormwind{/link} hat sich wieder erhoben, doch sein König wird vermisst, und sein Regent, {link:bolvar-fordragon}Bolvar Fordragon{/link}, hält ein Reich, dessen Kräfte bis zum Äußersten gespannt sind. {link:magni-bronzebeard}Magni Bronzebeard{/link} herrscht in {link:ironforge}Ironforge{/link}, das auch den Gnomen Zuflucht bietet, denn {link:gnomeregan}Gnomeregan{/link} ist an seinen eigenen Untergang verloren. Nördlich des Thandol-Übergangs ist das große Königreich {link:lordaeron}Lordaeron{/link} nicht mehr. Die {link:scourge}Geißel{/link} hält die Pestländer. Die Eiferer des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link} bekämpfen sie mit Feuer und Misstrauen zugleich. In den Ruinen der alten {link:capital-city}Hauptstadt{/link} haben sich die {link:forsaken}Verlassenen{/link} unter der Erde ein Zuhause geschaffen. Im {link:blackrock-mountain}Blackrock{/link} führen {link:dark-iron-dwarves}Dunkeleisen{/link} und {link:orcs}Orcs{/link} Krieg gegeneinander. Und im Süden steht das Dunkle Portal still in den {link:blasted-lands}Verwüsteten Landen{/link}.]=],
		},
	},
})

Translate("deDE", "kalimdor", {
	title = "Kalimdor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kalimdor liegt jenseits des Meeres im Westen der {link:eastern-kingdoms}Östlichen Königreiche{/link}. Es ist ein Land alter Wälder und roter Schluchten, großer Ebenen und brennender Wüsten. Es ist die Heimat der {link:night-elves}Nachtelfen{/link} und der {link:tauren}Tauren{/link} und das uralte Herz der Welt. Das Kalimdor von heute ist nur, was die {link:great-sundering}Große Zerschlagung{/link} überlebte. Vor jener Katastrophe umfasste ein einziger Kontinent nahezu alle Lande Azeroths, und der See in seiner Mitte war der {link:well-of-eternity}Brunnen der Ewigkeit{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die ältesten Völker Kalimdors waren die {link:trolls}Trolle{/link}, deren Reiche sich weit über den urzeitlichen Kontinent erstreckten. Ein Stamm von Trollen, der sich am Brunnen niederließ, wurde über viele Generationen von seiner Macht verändert. Sie wurden die {link:night-elves}Nachtelfen{/link}, die das Land Kalimdor nannten. Am Brunnen errichteten sie unter {link:queen-azshara}Königin Azshara{/link} die Städte des Reiches der Kaldorei. Ihr Streben nach {link:arcane-magic}arkaner Magie{/link} zog die {link:burning-legion}Brennende Legion{/link} in die Welt. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} wurde der Brunnen zerstört, und der Kontinent zersprang. Die Meere ergossen sich in die Wunde, und seither wirbelt dort der Mahlstrom. An den Hängen des Berges Hyjal pflanzten die Überlebenden {link:nordrassil}Nordrassil{/link}, und zehntausend Jahre lang hielten die Nachtelfen verborgen Wache über ihre Wälder.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die lange Wacht.{/b} Unter {link:malfurion-stormrage}Malfurion Stormrage{/link} und {link:tyrande-whisperwind}Tyrande Whisperwind{/link} schworen die {link:night-elves}Nachtelfen{/link} der arkanen Magie ab. Die Druiden schliefen im {link:emerald-dream}Smaragdgrünen Traum{/link}, und die {link:sentinels}Schildwachen{/link} hüteten die Wälder allein.
• {b}Die Völker der Wildnis.{/b} Über die Ebenen zogen die {link:tauren}Tauren{/link}. Über Generationen wurden sie bedrängt von den {link:centaurs}Zentauren{/link} des Südens, den {link:quilboar}Stachelebern{/link} des Brachlands, den {link:harpies}Harpyien{/link} der Klippen und den {link:furbolgs}Furbolgs{/link} der Wälder.
• {b}Der Dritte Krieg.{/b} Im {link:third-war}Dritten Krieg{/link} überquerte eine neue {link:horde}Horde{/link} unter {link:thrall}Thrall{/link} das Meer, und ebenso die {link:humans}Menschen{/link} von {link:jaina-proudmoore}Jaina Proudmoore{/link}. Die {link:burning-legion}Brennende Legion{/link} folgte ihnen. {link:orcs}Orc{/link}, Mensch und Nachtelf, einst Fremde und Feinde, standen gemeinsam in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}, und dort wurde {link:archimonde}Archimonde{/link} vernichtet.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Kalimdor ist kein verborgenes Land mehr. Die {link:night-elves}Nachtelfen{/link} haben einen neuen Baum gepflanzt, {link:teldrassil}Teldrassil{/link}, und seine Stadt {link:darnassus}Darnassus{/link} blickt über das nördliche Meer. Die {link:orcs}Orcs{/link} haben {link:durotar}Durotar{/link} und die Stadt {link:orgrimmar}Orgrimmar{/link} gegründet, und die {link:tauren}Tauren{/link} von {link:cairne-bloodhoof}Cairne Bloodhoof{/link} haben {link:thunder-bluff}Thunder Bluff{/link} in {link:mulgore}Mulgore{/link} zu ihrer Heimat gemacht. Die {link:darkspear-trolls}Trolle der Darkspear{/link} leben an der Seite der Orcs. {link:jaina-proudmoore}Jaina Proudmoore{/link} hält {link:theramore-isle}Theramore{/link} in den {link:dustwallow-marsh}Marschen von Dustwallow{/link}. Doch der Frieden von Hyjal bekommt Risse. Holzfäller der Orcs schlagen die Bäume des Eschentals, und die {link:sentinels}Schildwachen{/link} antworten mit Pfeilen. Goblins des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link} und der {link:venture-company}Venture Company{/link} handeln und plündern entlang der Küsten. Die Wälder des {link:felwood}Teufelswalds{/link} tragen noch immer den Makel der Legion, und ältere Geheimnisse schlafen in den Wüsten des Südens.]=],
		},
	},
})

Translate("deDE", "war-of-the-ancients", {
	title = "Krieg der Ahnen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Krieg der Ahnen war der erste Einfall der {link:burning-legion}Brennenden Legion{/link} in {link:azeroth}Azeroth{/link}. Er wurde etwa zehntausend Jahre vor der Öffnung des {link:dark-portal}Dunklen Portals{/link} geführt und beendete das Reich der Kaldorei. Seine letzte Stunde brachte die {link:great-sundering}Große Zerschlagung{/link}, die die Welt zerbrach.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Hochgeborenen am Hof der {link:night-elves}Nachtelfen{/link} schöpften immer tiefer aus der Macht des {link:well-of-eternity}Brunnens der Ewigkeit{/link}. Ihre Magie wurde jenseits der Welt von {link:sargeras}Sargeras{/link} gespürt, dem gefallenen Titanen, der die {link:burning-legion}Brennende Legion{/link} anführt. Er flüsterte {link:queen-azshara}Königin Azshara{/link} zu, und sie glaubte ihm. {link:azshara}Azshara{/link} und ihre Hochgeborenen arbeiteten daran, im Brunnen ein Tor zu öffnen, damit Sargeras und seine Dämonen {link:azeroth}Azeroth{/link} betreten konnten.]=],
		},
		{
			title = "Geschichte",
			text = [=[Die ersten Dämonen kamen hindurch, angeführt von {link:archimonde}Archimonde{/link} und {link:mannoroth}Mannoroth{/link}, und sie schlachteten die {link:night-elves}Nachtelfen{/link} ab, die sich ihnen in den Weg stellten. Gegen sie und gegen die Königin bildete sich ein Widerstand. Angeführt wurde er von {link:malfurion-stormrage}Malfurion Stormrage{/link}, einem jungen Schüler des Halbgotts {link:cenarius}Cenarius{/link}, gemeinsam mit der Priesterin {link:tyrande-whisperwind}Tyrande Whisperwind{/link} und Malfurions Zwillingsbruder {link:illidan-stormrage}Illidan Stormrage{/link}. Die Halbgötter der Wildnis und die Drachenschwärme schlossen sich dem Kampf an. Der Krieg war beinahe verloren, als der Erdwächter der Drachen seine Art verriet. Er war der Aspekt, der zu {link:deathwing}Todesschwinge{/link} werden sollte. Am Ende erreichten die Verteidiger den Palast der Hochgeborenen und brachen ihre Zauber, als {link:sargeras}Sargeras{/link} hindurchzutreten versuchte. Das Tor stürzte in sich zusammen, und der {link:well-of-eternity}Brunnen der Ewigkeit{/link} zerriss sich selbst.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Krieg lehrte die {link:night-elves}Nachtelfen{/link}, dass die arkane Magie die Welt beinahe ins Verderben gestürzt hätte. Sie schworen ihr ab, wandten sich dem Druidentum und der Verehrung Elunes zu und begannen ihre lange Wacht. Er ließ {link:illidan-stormrage}Illidan{/link} zudem in den Augen seines Volkes als Verräter zurück, denn er hatte heimlich mit den Hochgeborenen zusammengearbeitet, und danach schuf er einen neuen Brunnen auf dem Gipfel des Berges Hyjal.]=],
		},
	},
})

Translate("deDE", "great-sundering", {
	title = "Große Zerschlagung",
	aliases = { "Zerschlagung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Große Zerschlagung war die Katastrophe, die den {link:war-of-the-ancients}Krieg der Ahnen{/link} beendete. Als der {link:well-of-eternity}Brunnen der Ewigkeit{/link} zusammenbrach, zersprang der einzige Kontinent der alten Welt, und die Meere strömten herein, um die Wunde zu füllen. Das Antlitz Azeroths war für immer verändert.]=],
		},
		{
			title = "Geschichte",
			text = [=[In der letzten Stunde des Krieges wurde das Tor der Hochgeborenen aufgelöst. Der Brunnen, gespeist mit mehr Macht, als er fassen konnte, fiel in sich zusammen. Die Explosion riss das Herz aus dem Kontinent. Der größte Teil des Reiches der Kaldorei, mit seiner strahlenden {link:capital-city}Hauptstadt{/link} Zin-Azshari, wurde vom Meer verschlungen. {link:queen-azshara}Königin Azshara{/link} und viele ihrer Hochgeborenen wurden unter die Wellen gezogen. Wo der Brunnen gewesen war, begannen die Wasser zu kreisen, und der gewaltige Sturm, den man den Mahlstrom nennt, wurde geboren. Er hat nie aufgehört.]=],
		},
		{
			title = "Die Welt danach",
			text = [=[Nur Bruchstücke des alten Kontinents blieben über dem Wasser. Die größten von ihnen wurden {link:kalimdor}Kalimdor{/link} im Westen und die {link:eastern-kingdoms}Östlichen Königreiche{/link} im Osten, und das gefrorene Land Nordend lag im Norden. Die überlebenden {link:night-elves}Nachtelfen{/link} sammelten sich an den Hängen des Berges Hyjal. Dort fanden sie heraus, dass {link:illidan-stormrage}Illidan Stormrage{/link} Phiolen mit dem Wasser des Brunnens mitgenommen und in einen Bergsee gegossen hatte, wodurch ein zweiter Brunnen entstand. Um ihn zu schützen, pflanzten die Aspekte {link:nordrassil}Nordrassil{/link} über seinen Wassern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Für die {link:night-elves}Nachtelfen{/link} war die Zerschlagung der Beweis für den Preis der {link:arcane-magic}arkanen Magie{/link}. Für die Welt bedeutete sie zehntausend Jahre der Trennung. Die Völker des Ostens und des Westens vergaßen einander, bis der {link:third-war}Dritte Krieg{/link} sie wieder zusammenführte. Die {link:naga}Naga{/link}, die heute die Küsten heimsuchen, sollen die ertrunkenen Hochgeborenen sein, bis zur Unkenntlichkeit verwandelt.]=],
		},
	},
})

Translate("deDE", "troll-wars", {
	title = "Trollkriege",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Trollkriege wurden zwischen den Trollen der Amani und den jungen Königreichen der {link:humans}Menschen{/link} und der {link:high-elves}Hochelfen{/link} geführt, etwa zweitausendachthundert Jahre vor der Öffnung des {link:dark-portal}Dunklen Portals{/link}. Aus ihnen gingen das Bündnis von Elfen und Menschen und die ersten menschlichen Magier hervor.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die aus {link:kalimdor}Kalimdor{/link} verbannten Hochgeborenen gründeten {link:quel-thalas}Quel'Thalas{/link} in den nördlichen Wäldern der {link:eastern-kingdoms}Östlichen Königreiche{/link}. Diese Wälder hatten den Amani gehört, und die {link:trolls}Trolle{/link} vergaben den Raub nie. Tausende Jahre lang führten sie Krieg gegen die Elfen. Schließlich sammelten sie ein gewaltiges Heer, vielleicht verstärkt durch ihre Verwandten, die Gurubashi, und zogen aus, um Quel'Thalas gänzlich zu vernichten.]=],
		},
		{
			title = "Geschichte",
			text = [=[Im selben Zeitalter hatte {link:thoradin}Thoradin{/link} vom Stamm der {link:arathi-highlands}Arathi{/link} die Menschenstämme des Nordens zur Nation {link:arathor}Arathor{/link} geeint, mit ihrer {link:capital-city}Hauptstadt{/link} {link:stromgarde-keep}Strom{/link}. Die Elfen von {link:quel-thalas}Quel'Thalas{/link} sandten in ihrer Verzweiflung Gesandte zu ihm. Thoradin willigte ein, ihnen zu helfen, wenn die Elfen sein Volk die Magie lehrten. Die Elfen wählten einhundert {link:humans}Menschen{/link} mit einer Begabung für die Kunst und lehrten sie nur, was nötig war. Die verbündeten Heere trafen im Süden des Alteracgebirges auf das Heer der Amani. Die menschlichen Magier und die elfischen Magister riefen Feuer auf die {link:trolls}Trolle{/link} herab, und die Flammen brannten die Wunden aus, die Trolle sonst heilen können. Die Amani brachen ein und flohen, und ihr Reich erholte sich nie wieder.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aus Dankbarkeit schworen die Elfen von {link:quel-thalas}Quel'Thalas{/link} der Linie Thoradins einen Eid der Freundschaft. Dieser Eid sollte sie in den {link:second-war}Zweiten Krieg{/link} führen. Die Magie, die man die {link:humans}Menschen{/link} gelehrt hatte, verbreitete sich weit über die ersten Hundert hinaus. Aus ihr gingen {link:dalaran}Dalaran{/link} und die {link:kirin-tor}Kirin Tor{/link} hervor, und sie zog erneut die Aufmerksamkeit der {link:burning-legion}Brennenden Legion{/link} auf sich.]=],
		},
	},
})

Translate("deDE", "first-war", {
	title = "Erster Krieg",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Erste Krieg war der Einfall der orcischen {link:horde}Horde{/link} in das menschliche Königreich {link:azeroth}Azeroth{/link}. Er begann, als sich das {link:dark-portal}Dunkle Portal{/link} im Schwarzen Morast öffnete, und er endete mit dem Fall von {link:stormwind-city}Stormwind{/link}. Er war der erste Krieg zwischen {link:orcs}Orc{/link} und Mensch und der Beginn des Zeitalters, das die Welt seither geprägt hat.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Auf ihrer Welt Draenor waren die {link:orcs}Orcs{/link} von dem Dämonenfürsten {link:kil-jaeden}Kil'jaeden{/link} verderbt worden, durch den Hexenmeister {link:gul-dan}Gul'dan{/link} und seinen {link:shadow-council}Schattenrat{/link}. Ihre Heimat lag im Sterben. In {link:azeroth}Azeroth{/link} war {link:medivh}Medivh{/link}, der {link:the-night-watch}Wächter{/link} von {link:tirisfal-glades}Tirisfal{/link}, seit Langem vom Geist des {link:sargeras}Sargeras{/link} besessen. Im Zusammenwirken mit Gul'dan half Medivh, ein Tor zwischen den beiden Welten zu öffnen.]=],
		},
		{
			title = "Geschichte",
			text = [=[Die ersten {link:orcs}Orcs{/link} kamen in kleiner Zahl hindurch und plünderten im Schwarzen Morast. Dann weitete sich das Portal, und die {link:horde}Horde{/link} kam in voller Stärke, unter dem Kriegshäuptling Blackhand. König {link:llane-wrynn}Llane Wrynn{/link} und sein Streiter {link:anduin-lothar}Anduin Lothar{/link} bekämpften sie jahrelang im ganzen südlichen Königreich. Die Horde brannte die Höfe von {link:elwynn-forest}Elwynn{/link}, die Wälder des Dämmerwalds und die {link:northshire-abbey}Abtei von Nordhain{/link} nieder. Lothar und der junge Magier {link:khadgar}Khadgar{/link} erschlugen schließlich den wahnsinnigen {link:the-night-watch}Wächter{/link} in seinem Turm {link:karazhan}Karazhan{/link}. Für das Königreich war es zu spät. Die Halborcin {link:garona}Garona{/link} erschlug König Llane in seiner eigenen Burg, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} nahm Blackhand die Horde ab, und {link:stormwind-city}Stormwind{/link} wurde geplündert.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:anduin-lothar}Lothar{/link} führte die Überlebenden über das Meer nach Norden, nach {link:lordaeron}Lordaeron{/link}, und nahm Llanes Sohn {link:varian-wrynn}Varian{/link} mit sich. Ihre Warnungen veranlassten König {link:terenas-menethil}Terenas Menethil{/link}, die {link:alliance}Allianz{/link} zu sammeln und sich auf den {link:second-war}Zweiten Krieg{/link} vorzubereiten.]=],
		},
	},
})

Translate("deDE", "second-war", {
	title = "Zweiter Krieg",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Zweite Krieg wurde zwischen der {link:horde}Horde{/link} unter {link:orgrim-doomhammer}Orgrim Doomhammer{/link} und der {link:alliance}Allianz{/link} von {link:lordaeron}Lordaeron{/link} geführt. Die Horde marschierte nach Norden, um die Königreiche der {link:humans}Menschen{/link} zu erobern, die den {link:first-war}Ersten Krieg{/link} überlebt hatten. An der Blackrockspitze wurde sie zerschlagen.]=],
		},
		{
			title = "Geschichte",
			text = [=[König {link:terenas-menethil}Terenas Menethil{/link} von {link:lordaeron}Lordaeron{/link} vereinte die Königreiche der {link:humans}Menschen{/link} zu einer {link:alliance}Allianz{/link}, mit {link:anduin-lothar}Anduin Lothar{/link} als ihrem Befehlshaber. Die {link:dwarves}Zwerge{/link} von {link:kingdom-of-ironforge}Ironforge{/link} und die {link:gnomes}Gnome{/link} schlossen sich ihnen an. Ebenso die Elfen von {link:quel-thalas}Quel'Thalas{/link}, gebunden durch den alten Eid, den sie der Linie Thoradins geschworen hatten, denn Lothar war ihr letzter Erbe. Die {link:horde}Horde{/link} kam in größerer Stärke als zuvor. Doomhammer holte {link:ogres}Oger{/link} und die Amanitrolle von Zul'jin an seine Seite. Der Klan der {link:dragonmaw-clan}Dragonmaw{/link} versklavte den roten Drachenschwarm und ritt seine Drachen in die Schlacht. {link:gul-dan}Gul'dan{/link} erweckte Todesritter aus den Leichen gefallener menschlicher Ritter. Die Horde überrannte Khaz Modan und brannte die Grenzen von Quel'Thalas nieder. Lord Perenolde von {link:alterac-mountains}Alterac{/link} verriet die Allianz an die {link:orcs}Orcs{/link}. Die Horde erreichte sogar die Mauern der {link:capital-city}Hauptstadt{/link} Lordaerons.]=],
		},
		{
			title = "Die Wende des Krieges",
			text = [=[Auf dem Höhepunkt des Krieges ließ {link:gul-dan}Gul'dan{/link} Doomhammer im Stich. Er segelte mit seinen Anhängern davon, um das {link:the-sepulcher}Grabmal{/link} des {link:sargeras}Sargeras{/link} zu suchen, und die {link:horde}Horde{/link} war gezwungen, umzukehren, um ihn zu bestrafen. Die {link:alliance}Allianz{/link} ergriff die Gelegenheit. Sie trieb die Horde nach Süden bis zur Blackrockspitze. Dort fiel {link:anduin-lothar}Lothar{/link} von Doomhammers Hand. Sein Leutnant {link:turalyon}Turalyon{/link} ergriff sein Banner und zerschmetterte die Horde in der Brennenden Steppe.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die überlebenden {link:orcs}Orcs{/link} wurden in {link:internment-camps}Internierungslager{/link} getrieben. Das Dunkle Portal wurde zerstört. Die {link:alliance}Allianz{/link} hatte gesiegt, doch ihr Sieg war teuer erkauft. Ihre Königreiche stritten bald über die Kosten der Lager, und {link:gilneas}Gilneas{/link} und {link:stromgarde-keep}Stromgarde{/link} verließen die Allianz.]=],
		},
	},
})

Translate("deDE", "third-war", {
	title = "Dritter Krieg",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Dritte Krieg war der zweite Einfall der {link:burning-legion}Brennenden Legion{/link} in {link:azeroth}Azeroth{/link}. Er begann in {link:lordaeron}Lordaeron{/link} mit einer Seuche des Untodes und endete in {link:kalimdor}Kalimdor{/link} mit der Vernichtung von {link:archimonde}Archimonde{/link}. Er kostete die Menschheit ihr größtes Königreich und die {link:night-elves}Nachtelfen{/link} ihre Unsterblichkeit.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach dem Zweiten Krieg band der Dämon {link:kil-jaeden}Kil'jaeden{/link} den Geist des orcischen Schamanen {link:ner-zhul}Ner'zhul{/link} in einem gefrorenen Gefängnis in Nordend und machte ihn zum Lichkönig. Durch den Nekromanten {link:kel-thuzad}Kel'Thuzad{/link} und seinen {link:cult-of-the-damned}Kult der Verdammten{/link} verbreitete der Lichkönig eine Seuche in den Dörfern Lordaerons. Ihre Opfer erhoben sich als die untote {link:scourge}Geißel{/link}. Zur selben Zeit befreite der junge {link:orcs}Orc{/link} {link:thrall}Thrall{/link} sein Volk aus den Internierungslagern und schmiedete eine neue {link:horde}Horde{/link}.]=],
		},
		{
			title = "Geschichte",
			text = [=[Ein geheimnisvoller Prophet warnte die Könige des Ostens, über das Meer nach Westen zu fliehen. König {link:terenas-menethil}Terenas Menethil{/link} wollte nicht hören, doch {link:thrall}Thrall{/link} und {link:jaina-proudmoore}Jaina Proudmoore{/link} folgten dem Ruf. Der Prophet war {link:medivh}Medivh{/link}, aus dem Tod zurückgekehrt. In {link:lordaeron}Lordaeron{/link} verfolgte Prinz {link:arthas-menethil}Arthas Menethil{/link} die Seuche bis zu ihrem Ursprung. Nach dem {link:culling-of-stratholme}Ausmerzen von Stratholme{/link} segelte er nach Nordend und nahm die verfluchte Klinge Frostgram an sich. Er kehrte als Todesritter zurück und führte den {link:fall-of-lordaeron}Fall von Lordaeron{/link} herbei. Die {link:scourge}Geißel{/link} erweckte {link:kel-thuzad}Kel'Thuzad{/link} am Sonnenbrunnen von {link:quel-thalas}Quel'Thalas{/link}, und {link:archimonde}Archimonde{/link} betrat die Welt in {link:dalaran}Dalaran{/link} und zerstörte es. Dann folgte die Legion der {link:horde}Horde{/link} und den {link:humans}Menschen{/link} nach {link:kalimdor}Kalimdor{/link}. Dort erhoben sich die {link:night-elves}Nachtelfen{/link} aus ihrer Wacht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:orcs}Orcs{/link}, {link:humans}Menschen{/link} und {link:night-elves}Nachtelfen{/link} machten endlich gemeinsame Sache. In der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} vernichteten sie {link:archimonde}Archimonde{/link}. Aus dem Krieg gingen die Lande der neuen {link:horde}Horde{/link} in {link:kalimdor}Kalimdor{/link}, die {link:theramore-isle}Stadt Theramore{/link} und die {link:forsaken}Verlassenen{/link} hervor. Seine Wunden sind noch offen.]=],
		},
	},
})

Translate("deDE", "battle-of-mount-hyjal", {
	title = "Schlacht am Berg Hyjal",
	aliases = { "Schlacht um Hyjal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schlacht am Berg Hyjal war die letzte Schlacht des {link:third-war}Dritten Krieges{/link}. An den Hängen des heiligen Berges standen {link:orcs}Orcs{/link}, {link:humans}Menschen{/link} und {link:night-elves}Nachtelfen{/link} gemeinsam gegen die {link:burning-legion}Brennende Legion{/link}. Der Dämonenfürst {link:archimonde}Archimonde{/link} wurde an den Wurzeln von {link:nordrassil}Nordrassil{/link} vernichtet.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Legion war des Weltenbaums wegen nach {link:kalimdor}Kalimdor{/link} gekommen. {link:archimonde}Archimonde{/link} wollte die Macht des zweiten Brunnens der Ewigkeit aussaugen, der unter seinen Wurzeln lag, und so die Welt verschlingen. Die {link:scourge}Geißel{/link} marschierte vor ihm her. Die {link:night-elves}Nachtelfen{/link} von {link:tyrande-whisperwind}Tyrande Whisperwind{/link} und {link:malfurion-stormrage}Malfurion Stormrage{/link} konnten nicht allein bestehen. {link:medivh}Medivh{/link} brachte ihre Anführer mit {link:thrall}Thrall{/link} von der {link:horde}Horde{/link} und {link:jaina-proudmoore}Jaina Proudmoore{/link} von den {link:humans}Menschen{/link} zusammen. Er sagte ihnen, dass sie nur gemeinsam überleben könnten.]=],
		},
		{
			title = "Geschichte",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} ersann den Plan. Die {link:humans}Menschen{/link} hielten an den unteren Hängen stand, dann die {link:orcs}Orcs{/link} weiter oben, und jeder hielt so lange aus, wie er konnte, bevor er zurückwich. Während sie kämpften, bereitete Malfurion auf dem Gipfel eine Falle vor. {link:archimonde}Archimonde{/link} durchbrach eine Linie nach der anderen und erreichte schließlich den Baum. Als er {link:nordrassil}Nordrassil{/link} hinaufstieg, blies Malfurion das Horn des {link:cenarius}Cenarius{/link}. Die Geister der Ahnen der {link:night-elves}Nachtelfen{/link}, versammelt als unzählige Irrwische, fielen über den Dämon her. Ihre Macht und die Macht des Weltenbaums wurden in einer einzigen Entladung freigesetzt. Archimonde wurde vernichtet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Sieg rettete die Welt, doch er hatte einen hohen Preis. {link:nordrassil}Nordrassil{/link} gab seine Macht her, und die {link:night-elves}Nachtelfen{/link} verloren die Unsterblichkeit, die er ihnen geschenkt hatte. Der Baum war versengt, doch nicht getötet. Die Schlacht schmiedete zudem einen kurzen Frieden zwischen der {link:alliance}Allianz{/link} und der {link:horde}Horde{/link}.]=],
		},
	},
})

Translate("deDE", "culling-of-stratholme", {
	title = "Das Ausmerzen von Stratholme",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Ausmerzen von Stratholme war die Abschlachtung der Bewohner Stratholmes durch die Soldaten von Prinz {link:arthas-menethil}Arthas Menethil{/link}. Es geschah im {link:third-war}Dritten Krieg{/link}, als die Seuche des Untodes die Stadt erreichte. Es markierte den Beginn des Falls des Prinzen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[{link:arthas-menethil}Arthas{/link} hatte die Seuche mit der Zauberin {link:jaina-proudmoore}Jaina Proudmoore{/link} und seinem Mentor {link:uther-the-lightbringer}Uther dem Lichtbringer{/link} quer durch {link:lordaeron}Lordaeron{/link} verfolgt. Er erfuhr, dass der {link:cult-of-the-damned}Kult der Verdammten{/link} das Getreide verseucht hatte, das aus den Kornspeichern von {link:ruins-of-andorhal}Andorhal{/link} verschifft wurde. In Stratholme stellte er fest, dass das verseuchte Getreide bereits ausgegeben worden war. Jeder, der davon gegessen hatte, würde bald sterben und sich als Teil der {link:scourge}Geißel{/link} wieder erheben.]=],
		},
		{
			title = "Geschichte",
			text = [=[{link:arthas-menethil}Arthas{/link} befahl, die Stadt zu säubern, bevor sich ihre Bewohner verwandeln konnten. {link:uther-the-lightbringer}Uther{/link} weigerte sich, daran teilzunehmen, und Arthas enthob ihn wegen Verrats seines Kommandos. {link:jaina-proudmoore}Jaina{/link} wollte nicht zusehen und verließ ihn. Der Prinz führte die Soldaten, die ihm treu blieben, nach Stratholme und tötete seine Bewohner mit dem Schwert, Haus für Haus. Wo sie noch nicht angekommen waren, verwandelten sich die Bürger bereits. Der Schreckenslord Mal'Ganis wartete in der Stadt. Er verhöhnte den Prinzen und forderte ihn heraus, ihm nach Nordend zu folgen. Arthas schwor, ihn zur Strecke zu bringen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Das Ausmerzen zerbrach das Band zwischen {link:arthas-menethil}Arthas{/link} und denen, die ihn liebten. Es trieb ihn nach Norden, zu Frostgram und zum {link:fall-of-lordaeron}Fall von Lordaeron{/link}.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Stratholme liegt in Trümmern in den {link:eastern-plaguelands}Östlichen Pestländern{/link}. Die {link:scourge}Geißel{/link} hält einen großen Teil der Stadt. Der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} klammert sich an den Rest und kämpft noch immer gegen die Toten, die das Schwert des {link:arthas-menethil}Arthas{/link} nicht retten konnte.]=],
		},
	},
})

Translate("deDE", "fall-of-lordaeron", {
	title = "Der Fall von Lordaeron",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Fall von Lordaeron war der Untergang des größten Königreichs der {link:humans}Menschen{/link} durch die {link:scourge}Geißel{/link}. Er kam im {link:third-war}Dritten Krieg{/link}, als Prinz {link:arthas-menethil}Arthas Menethil{/link} als Diener des Lichkönigs aus Nordend zurückkehrte. Von allen Königreichen, die die {link:alliance}Allianz{/link} angeführt hatten, fiel keines so tief oder so schnell.]=],
		},
		{
			title = "Geschichte",
			text = [=[In Nordend nahm {link:arthas-menethil}Arthas{/link} die Runenklinge Frostgram an sich und erschlug den Schreckenslord Mal'Ganis. Er verlor seine Seele an die Klinge. Er segelte heim, und die Bewohner der {link:capital-city}Hauptstadt{/link} begrüßten ihn als Helden. Er schritt in den Thronsaal und erschlug seinen Vater, König {link:terenas-menethil}Terenas Menethil{/link}. Hinter ihm fegte die {link:scourge}Geißel{/link} über das Königreich. Arthas tötete {link:uther-the-lightbringer}Uther den Lichtbringer{/link} und nahm die Asche aus der Urne seines Vaters, damit die Überreste von {link:kel-thuzad}Kel'Thuzad{/link} darin getragen werden konnten. Er marschierte in {link:quel-thalas}Quel'Thalas{/link} ein, schlug dessen Verteidiger unter {link:sylvanas-windrunner}Sylvanas Windrunner{/link} nieder und erweckte Kel'Thuzad in den Wassern des Sonnenbrunnens. Bald darauf half die Geißel {link:archimonde}Archimonde{/link}, die Welt in {link:dalaran}Dalaran{/link} zu betreten.]=],
		},
		{
			title = "Nach dem Fall",
			text = [=[Als {link:archimonde}Archimonde{/link} vernichtet war, strebten die Schreckenslords danach, das zerstörte Königreich selbst zu beherrschen. {link:arthas-menethil}Arthas{/link} wandte sich gegen sie, bevor er dem Ruf seines Meisters in den Norden folgte. {link:sylvanas-windrunner}Sylvanas{/link}, nun untot, befreite sich vom Willen des Lichkönigs. Sie und ihre {link:forsaken}Verlassenen{/link} stürzten die Schreckenslords und beanspruchten die Ruinen der {link:capital-city}Hauptstadt{/link}.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[{link:lordaeron}Lordaeron{/link} ist dahin. Sein Kernland sind die Pestländer, von der {link:scourge}Geißel{/link} gehalten. Der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} bekämpft die Toten in {link:tirisfal-glades}Tirisfal{/link} und darüber hinaus. Unter dem zerbrochenen Thronsaal haben die Verlassenen {link:undercity}Undercity{/link} erbaut.]=],
		},
	},
})

Translate("deDE", "dark-portal", {
	title = "Dunkles Portal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Dunkle Portal ist das große Tor zwischen {link:azeroth}Azeroth{/link} und Draenor, der Heimat der {link:orcs}Orcs{/link}. Es steht in den {link:blasted-lands}Verwüsteten Landen{/link}, die einst die Sümpfe des Schwarzen Morasts waren. Durch es kam die {link:horde}Horde{/link}, und mit ihm begann der {link:first-war}Erste Krieg{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Das Portal wurde von dem Hexenmeister {link:gul-dan}Gul'dan{/link} und seinem {link:shadow-council}Schattenrat{/link} auf Draenor geöffnet, mit der Hilfe von {link:medivh}Medivh{/link} auf {link:azeroth}Azeroth{/link}. Medivh war der {link:the-night-watch}Wächter{/link} von {link:tirisfal-glades}Tirisfal{/link}, doch sein Geist wurde seit Langem von {link:sargeras}Sargeras{/link} gehalten, dem Herrn der {link:burning-legion}Brennenden Legion{/link}. Anfangs war der Riss schmal, und nur wenige Späher kamen hindurch. Dann wurde er geweitet, und die ganze {link:horde}Horde{/link} zog in den Sumpf hinüber.]=],
		},
		{
			title = "Geschichte",
			text = [=[Die {link:horde}Horde{/link} errichtete eine große Festung um das Portal, und es wurde ihr Weg für Verstärkungen. Als der {link:second-war}Zweite Krieg{/link} verloren war, zerstörte die {link:alliance}Allianz{/link} das Dunkle Portal. Einige Jahre später öffnete der Schamane {link:ner-zhul}Ner'zhul{/link} es erneut und führte eine neue Horde hindurch, um Artefakte der Macht zu stehlen. Die Allianz sandte eine Expedition hinüber nach Draenor, um die Bedrohung an ihrem Ursprung zu beenden. Ner'zhul riss Spalten zu anderen Welten auf, und das Portal wurde abermals zerstört. Die Expedition kehrte nicht zurück. Niemand in {link:azeroth}Azeroth{/link} weiß, was aus ihr geworden ist.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Das Dunkle Portal steht dunkel und still am südlichen Ende der Verwüsteten Lande. Die Magier und Soldaten von {link:nethergarde-keep}Burg Nethergarde{/link} wachen darüber. Noch immer streifen Dämonen durch das öde Land ringsum.]=],
		},
	},
})

Translate("deDE", "well-of-eternity", {
	title = "Brunnen der Ewigkeit",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Brunnen der Ewigkeit war ein gewaltiger See arkaner Macht im Herzen der alten Welt. An seinen Ufern erhob sich das Reich der Kaldorei. Seine Zerstörung beendete den {link:war-of-the-ancients}Krieg der Ahnen{/link} und verursachte die {link:great-sundering}Große Zerschlagung{/link}.]=],
		},
		{
			title = "Wesen",
			text = [=[Die ältesten Geschichten berichten, dass der Brunnen eine Wunde in der Erde füllte, die der Krieg der Titanen gegen die Alten Götter hinterlassen hatte. Seine Wasser waren schwarz und tief, und sie bargen die rohe Macht der Welt selbst. Die {link:trolls}Trolle{/link}, die sich in seiner Nähe niederließen, wurden über viele Generationen verändert und wurden zu den {link:night-elves}Nachtelfen{/link}. Sie lernten, seine Macht zu führen, und ihre Meisterschaft in der {link:arcane-magic}arkanen Magie{/link} machte ihr Reich zum Wunder der Welt.]=],
		},
		{
			title = "Geschichte",
			text = [=[Die Königin der {link:night-elves}Nachtelfen{/link}, {link:queen-azshara}Azshara{/link}, erbaute ihren Palast an den Ufern des Brunnens, und ihre Hochgeborenen schöpften immer tiefer aus ihm. Ihre Magie lockte die {link:burning-legion}Brennende Legion{/link} an. Die Hochgeborenen versuchten, im Brunnen selbst ein Tor für {link:sargeras}Sargeras{/link} zu öffnen. Als das Tor aufgelöst wurde, brach der Brunnen zusammen, und der Kontinent wurde zerrissen. Wo er gewesen war, tobt nun der Mahlstrom.]=],
		},
		{
			title = "Sein Vermächtnis",
			text = [=[Etwas vom Brunnen überlebte. {link:illidan-stormrage}Illidan Stormrage{/link} rettete Phiolen mit seinem Wasser und goss sie in einen See auf dem {link:mount-hyjal}Berg Hyjal{/link}, wodurch ein zweiter Brunnen entstand. Dort pflanzten die Aspekte {link:nordrassil}Nordrassil{/link}. Die verbannten Hochgeborenen trugen eine weitere Phiole nach Osten. Mit ihr schufen sie den Sonnenbrunnen, die Quelle von {link:quel-thalas}Quel'Thalas{/link}. Im {link:third-war}Dritten Krieg{/link} kam {link:archimonde}Archimonde{/link} nach {link:kalimdor}Kalimdor{/link}, um die Macht des zweiten Brunnens zu verschlingen, und er scheiterte.]=],
		},
	},
})

Translate("deDE", "nordrassil", {
	title = "Nordrassil",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nordrassil ist der Weltenbaum, der sich auf dem Gipfel des Berges Hyjal in {link:kalimdor}Kalimdor{/link} erhebt. Zehntausend Jahre lang schützte er den zweiten {link:well-of-eternity}Brunnen der Ewigkeit{/link} und schenkte den {link:night-elves}Nachtelfen{/link} ihre Unsterblichkeit. Er war der Mittelpunkt der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach der {link:great-sundering}Großen Zerschlagung{/link} fanden die überlebenden {link:night-elves}Nachtelfen{/link} heraus, dass {link:illidan-stormrage}Illidan Stormrage{/link} einen neuen Brunnen auf dem Gipfel des Berges Hyjal geschaffen hatte. Die Aspekte der Drachen kamen zu ihnen. {link:alexstrasza}Alexstrasza{/link} legte einen heiligen Samen in die Wasser des neuen Brunnens, und ein großer Baum wuchs daraus empor, dessen Wurzeln aus dem Brunnen tranken und ihn versiegelten. Nozdormu segnete den Baum, damit die Nachtelfen lebten, solange er stand. Ysera band ihn an den {link:emerald-dream}Smaragdgrünen Traum{/link}, damit die Druiden durch ihn den Traum betreten konnten.]=],
		},
		{
			title = "Geschichte",
			text = [=[Unter seinen Ästen hielten die {link:night-elves}Nachtelfen{/link} ihre lange Wacht. Die Druiden von {link:malfurion-stormrage}Malfurion Stormrage{/link} schliefen in seinem Schatten, während ihre Geister durch den Traum wanderten. Im {link:third-war}Dritten Krieg{/link} marschierte {link:archimonde}Archimonde{/link} auf den Baum zu, um den Brunnen unter ihm auszusaugen. Als er seinen Stamm hinaufstieg, rief Malfurion die Geister der Ahnen, und die Macht Nordrassils wurde verbraucht, um den Dämon zu vernichten.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Nordrassil steht noch, vernarbt und geschwächt. Die {link:night-elves}Nachtelfen{/link} sind nicht länger unsterblich. Sie haben vor der Nordküste einen neuen Baum gepflanzt, {link:teldrassil}Teldrassil{/link}, doch er wuchs ohne den Segen der Aspekte heran. Viele der alten Druiden bezweifeln, dass er überhaupt hätte gepflanzt werden sollen.]=],
		},
	},
})

Translate("deDE", "holy-light", {
	title = "Heiliges Licht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Heilige Licht ist die Macht des Glaubens und der Tugend, die den Hingebungsvollen antwortet. Seine Priester heilen Wunden und richten Geister auf. Seine Paladine tragen es als Schild und als Waffe gegen die Untoten und die Dämonen in die Schlacht. Die meisten {link:humans}Menschen{/link} der {link:eastern-kingdoms}Östlichen Königreiche{/link} sind in seinem Glauben aufgewachsen, und viele {link:dwarves}Zwerge{/link} teilen ihn heute.]=],
		},
		{
			title = "Wesen",
			text = [=[Die Gläubigen lehren nicht, dass das Licht ein Gott ist. Sie lehren, dass es in allen wohnt, die nach Tugend streben, und dass es durch Mitgefühl, Mut und Opfer stärker wird. Es kann nicht gestohlen oder zur Grausamkeit gebeugt werden. Wer es ohne Glauben zu führen versucht, stellt fest, dass es ihm nicht antwortet.]=],
		},
		{
			title = "Geschichte",
			text = [=[Der Glaube an das Licht hat unter den {link:humans}Menschen{/link} tiefe Wurzeln, die bis in die Tage von {link:arathor}Arathor{/link} zurückreichen. Im {link:kingdom-of-stormwind}Königreich Stormwind{/link} wurde er in der {link:northshire-abbey}Abtei von Nordhain{/link} und in der {link:cathedral-of-light}Kathedrale des Lichts{/link} gepflegt. Nach dem {link:first-war}Ersten Krieg{/link} erkannte Erzbischof {link:alonsus-faol}Alonsus Faol{/link}, dass der Glaube allein den Süden nicht gerettet hatte. Er vereinte die Kleriker des Lichts mit den besten Rittern Lordaerons und gründete den Orden der Silbernen Hand, die ersten Paladine. {link:uther-the-lightbringer}Uther der Lichtbringer{/link} war der Erste von ihnen. Die Paladine kämpften im {link:second-war}Zweiten Krieg{/link} mit Ehre. Im {link:third-war}Dritten Krieg{/link} wurde der Orden zerrissen. Prinz {link:arthas-menethil}Arthas Menethil{/link} war einer von ihnen gewesen.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Das Licht ist noch immer das Herz von Stormwinds Glauben, und seine Priester dienen in jeder Stadt. In {link:lordaeron}Lordaeron{/link} ist es zu einem Schlachtruf geworden. Der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} verbrennt im Namen des Lichts alle, die er der Seuche verdächtigt. Die {link:argent-dawn}Argentumdämmerung{/link} bekämpft dieselben Toten mit ruhigerer Hand.]=],
		},
	},
})

Translate("deDE", "arcane-magic", {
	title = "Arkane Magie",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die arkane Magie ist die Magie des Geistes und der Muster der Welt. Ihre Meister beugen Raum und Zeit, beschwören Feuer und Frost und sehen, was andere nicht sehen können. Sie ist die älteste erlernte Magie Azeroths und die gefährlichste für jene, die sie zu sehr lieben.]=],
		},
		{
			title = "Wesen",
			text = [=[Arkane Macht kann von jenen erlernt werden, die Begabung und Disziplin besitzen, doch sie schenkt nichts umsonst. Wer sie führt, beginnt nach ihr zu gieren. Zudem ruft sie die Dämonen der {link:burning-legion}Brennenden Legion{/link}, die nach Welten voller Magie hungern. Jedes große Zeitalter arkaner Macht in {link:azeroth}Azeroth{/link} hat den Blick der Legion auf sich gezogen.]=],
		},
		{
			title = "Geschichte",
			text = [=[Die {link:night-elves}Nachtelfen{/link} meisterten die arkane Magie zuerst am {link:well-of-eternity}Brunnen der Ewigkeit{/link}, und ihre Hochgeborenen nutzten sie, um den {link:war-of-the-ancients}Krieg der Ahnen{/link} herbeizuführen. Nach der {link:great-sundering}Großen Zerschlagung{/link} verboten die Nachtelfen sie. Die Hochgeborenen, die nicht von ihr lassen wollten, wurden verbannt. Sie gründeten {link:quel-thalas}Quel'Thalas{/link} im Osten und wurden zu den {link:high-elves}Hochelfen{/link}. In den {link:troll-wars}Trollkriegen{/link} lehrten sie einhundert {link:humans}Menschen{/link} von {link:arathor}Arathor{/link} die Magie. Die Kunst verbreitete sich in den Landen der Menschen. Die Magier von Arathor errichteten die Stadt {link:dalaran}Dalaran{/link}, und ihr herrschender Rat, die {link:kirin-tor}Kirin Tor{/link}, wachte über den Gebrauch der Magie. Als in den Landen der Menschen Dämonen aufzutauchen begannen, gründeten die Elfen und die Magier den geheimen Rat von {link:tirisfal-glades}Tirisfal{/link}. Sie erwählten einen {link:the-night-watch}Wächter{/link}, der allein gegen die Legion kämpfen sollte. Die letzten Wächter waren {link:aegwynn}Aegwynn{/link} und ihr Sohn {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[{link:dalaran}Dalaran{/link} wurde im {link:third-war}Dritten Krieg{/link} von {link:archimonde}Archimonde{/link} zerstört. Nun bauen seine Magier es hinter einer schimmernden violetten Barriere in den Ausläufern von {link:alterac-mountains}Alterac{/link} wieder auf. Noch immer werden in {link:stormwind-city}Stormwind{/link}, {link:ironforge}Ironforge{/link} und {link:theramore-isle}Theramore{/link} Magier ausgebildet. Bei den {link:night-elves}Nachtelfen{/link} gilt das alte Gesetz gegen die arkane Magie fort.]=],
		},
	},
})

Translate("deDE", "fel-magic", {
	title = "Teufelsmagie",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Teufelsmagie ist die Magie der {link:burning-legion}Brennenden Legion{/link}. Sie bezieht ihre Macht aus Zerstörung und aus dem Raub von Leben. Sie brennt in einem kränklich grünen Feuer, und sie vergiftet das Land und die Seelen derer, die sie nutzen. Hexenmeister feilschen noch immer mit ihr, im Wissen um den Preis.]=],
		},
		{
			title = "Wesen",
			text = [=[Teufelsmacht ist schnell und stark, und sie verlangt wenig Studium. Stattdessen verlangt sie, dass etwas verzehrt wird: ein Leben, eine Seele, die Gesundheit des Landes. Wer sie nutzt, wird langsam verändert, an Leib und Herz. Orte, an denen sie oft genutzt wurde, verdorren und verrotten.]=],
		},
		{
			title = "Geschichte",
			text = [=[Die Teufelsmagie kam zuerst mit der Legion im {link:war-of-the-ancients}Krieg der Ahnen{/link} nach {link:azeroth}Azeroth{/link}. Viele Hochgeborene, die den Dämonen dienten, wurden zu {link:satyrs}Satyrn{/link} verzerrt. Zehntausend Jahre später kam sie erneut, durch die {link:orcs}Orcs{/link}. Auf Draenor lehrte der Dämonenfürst {link:kil-jaeden}Kil'jaeden{/link} {link:gul-dan}Gul'dan{/link} und seine Hexenmeister ihre Geheimnisse. Die Häuptlinge der Orcs tranken das Blut des Dämons {link:mannoroth}Mannoroth{/link}, und es erfüllte sie mit einer schrecklichen Wut. Das Land Draenor starb unter ihrer Magie. Die Orcs trugen den Fluch durch das {link:dark-portal}Dunkle Portal{/link} in den {link:first-war}Ersten Krieg{/link} und den {link:second-war}Zweiten Krieg{/link}. Im {link:third-war}Dritten Krieg{/link} erschlug {link:grom-hellscream}Grom Hellscream{/link} Mannoroth und befreite sein Volk vom Blut des Dämons, um den Preis seines eigenen Lebens. {link:illidan-stormrage}Illidan Stormrage{/link} verschlang den {link:skull-of-gul-dan}Schädel von Gul'dan{/link} und nahm die Macht eines Dämons an.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Die Wälder des {link:felwood}Teufelswalds{/link} tragen noch immer den Makel der Legion. Die Hexenmeister der {link:burning-blade}Brennenden Klinge{/link} dienen Dämonen in den Schatten von {link:orgrimmar}Orgrimmar{/link} und {link:durotar}Durotar{/link}. Die {link:satyrs}Satyrn{/link} suchen das {link:ashenvale}Eschental{/link} heim. Hexenmeister der {link:alliance}Allianz{/link} und der {link:horde}Horde{/link} studieren die Kunst noch immer. Sie beharren darauf, dass sie ihre Meister sind.]=],
		},
	},
})

Translate("deDE", "emerald-dream", {
	title = "Smaragdgrüner Traum",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Smaragdgrüne Traum ist ein weites Geisterreich, das die Welt widerspiegelt. Er zeigt {link:azeroth}Azeroth{/link} so, wie es hätte sein können, wild und unberührt von den Händen der Sterblichen. Seine Hüterin ist Ysera, der Aspekt des grünen Drachenschwarms. Die Druiden der {link:night-elves}Nachtelfen{/link} durchwandern ihn im Geist, während ihre Körper schlafen.]=],
		},
		{
			title = "Wesen",
			text = [=[Die Chroniken besagen, dass die Titanen den Traum als lebendes Abbild ihres Entwurfs für die Welt formten. Er ist das Reich des Wachstums und der Träume. Die grünen Drachen bewachen seine Tore, und die Geister der Wildnis wohnen in ihm. Zeit und Entfernung folgen dort nicht den Regeln der wachen Welt.]=],
		},
		{
			title = "Geschichte",
			text = [=[Der Halbgott {link:cenarius}Cenarius{/link} lehrte {link:malfurion-stormrage}Malfurion Stormrage{/link} die Wege des Druidentums, und durch sie lernte Malfurion, den Traum zu betreten. Nach dem {link:war-of-the-ancients}Krieg der Ahnen{/link} band Ysera {link:nordrassil}Nordrassil{/link} an den Traum. Tausende Jahre lang schliefen die Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link} in verborgenen Grabhügeln, während ihre Geister durch den Traum wanderten und die {link:sentinels}Schildwachen{/link} ihre Körper bewachten. Sie wurden geweckt, um im {link:third-war}Dritten Krieg{/link} zu kämpfen. Nach dem Sieg kehrten die Druiden zu ihrem Werk zurück.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} ist erneut in den Traum gegangen, und er ist nicht zurückgekehrt. {link:fandral-staghelm}Fandral Staghelm{/link} führt die Druiden in seiner Abwesenheit. Etwas stimmt nicht im Traum. Grüne Drachen werden in der wachen Welt gesehen, und manche von ihnen sind nicht mehr, was sie einst waren. Die Druiden von {link:moonglade}Moonglade{/link} sprechen von einer Finsternis, die sich im Traum ausbreitet und die noch niemand benennen kann.]=],
		},
	},
})

Translate("deDE", "elements", {
	title = "Elemente",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Elemente sind die lebendigen Kräfte von Erde, Feuer, Wasser und Luft. In ihrer rohen Form sind sie wild und zerstörerisch. Im Gleichgewicht erhalten sie die Welt. Die Schamanen der {link:orcs}Orcs{/link}, der {link:tauren}Tauren{/link} und der {link:trolls}Trolle{/link} sprechen mit den Geistern der Elemente und bitten sie um Hilfe.]=],
		},
		{
			title = "Wesen",
			text = [=[Vier große Elementarfürsten herrschen über die Elemente. Ragnaros ist der Herr des Feuers. Therazane ist die Mutter des Steins. {link:al-akir}Al'Akir{/link} ist der Herr der Winde, dessen Reich {link:skywall}Skywall{/link} ist. Neptulon ist der Herr der Gezeiten. Ihre Diener sind wild und dem sterblichen Leben feindlich gesinnt. Mit den geringeren Geistern jedoch lässt sich reden. Ein Schamane befiehlt ihnen nicht. Ein Schamane bittet, und die Geister entscheiden, ob sie antworten.]=],
		},
		{
			title = "Geschichte",
			text = [=[Im ersten Zeitalter der Welt kämpften die Elementarfürsten für die Alten Götter. Die Titanen besiegten sie und banden sie in einem Reich, das von der Welt getrennt ist. Auf Draenor waren die {link:orcs}Orcs{/link} ein Volk von Schamanen. Als {link:gul-dan}Gul'dan{/link} sie der Dämonenmagie zuwandte, verließen die Geister sie. Viel später, in Khaz Modan, beschwor der Than der {link:dark-iron-dwarves}Dunkeleisen{/link}, {link:ruins-of-thaurissan}Thaurissan{/link}, Ragnaros in die Welt. Die Beschwörung tötete den Than und türmte den {link:blackrock-mountain}Blackrock{/link} auf. Seither wohnt Ragnaros unter ihm. Nach dem {link:second-war}Zweiten Krieg{/link} lehrte der alte Schamane {link:drek-thar}Drek'Thar{/link} den jungen {link:thrall}Thrall{/link} die Wege der Geister. Die Elemente antworteten der neuen {link:horde}Horde{/link}, wie sie der alten nicht geantwortet hatten.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Ragnaros beherrscht die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} aus den geschmolzenen Tiefen des {link:blackrock-mountain}Blackrock{/link}. Der {link:twilight-s-hammer}Schattenhammer{/link} strebt danach, die Elemente für seine eigenen Zwecke zu erwecken. Die Schamanen der {link:horde}Horde{/link} bewahren das alte Gleichgewicht, wie es ihre Ahnen taten, bevor die Dämonen kamen.]=],
		},
	},
})
